// PF-24w (rows rev 16.5 "fail closed. Never default to the most permissive setting"; map row 15, J-15; SA-8-1, SA-8-4,
// SA-8-6, NFR5-05): PLATFORM_ENVIRONMENT is required with no default, and PF-24's one loader (config/settings.ts) reads
// every setting, PF-4's sign-in and Sample-seed settings included, once per process. Each "Done when" line of the brief
// is one case below, named as the brief names it. Every key here is generated by this run (node:crypto), never a real
// one. Spawns one server that must refuse to start, and starts two isolated copies of its own (local, then test with a
// counting preload) that it stops again. No model call (US$0).
//   tsx studio/tests/check_pf24w_environment.ts [port=4596] [name=pf24w]   (starts its own isolated copies)
import { execFileSync, spawn } from "node:child_process";
import { randomBytes } from "node:crypto";
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { createConnection } from "node:net";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { inspect } from "node:util";
import { ConfigRefused, loadPlatformConfig, SECRET_SETTING_NAMES, SETTINGS } from "../api/src/platform/config/settings.ts";

const PORT = Number(process.argv[2] ?? 4596), NAME = process.argv[3] ?? "pf24w";   // a lane passes its own port and name
const STUDIO = join(import.meta.dirname, "..");
let pass = 0, fail = 0;
const ok = (name: string, c: unknown, detail?: unknown) => { c ? pass++ : fail++; console.log(`${c ? "PASS" : "FAIL"}  ${name}${!c && detail !== undefined ? ` — ${String(typeof detail === "string" ? detail : JSON.stringify(detail)).slice(0, 500)}` : ""}`); };
const refusal = (f: () => unknown): ConfigRefused | null => { try { f(); return null; } catch (e) { return e instanceof ConfigRefused ? e : null; } };
const rand = (n: number) => randomBytes(n).toString("hex").slice(0, n);
const key32 = () => randomBytes(32).toString("base64");
/** A complete test/production configuration, every value made by this run (as check_pf24_secrets.ts). */
const generated = (): Record<string, string> => ({
  DATABASE_URL: `postgresql://pf24wuser:${rand(24)}@127.0.0.1:54329/pf24wdb`,
  PLATFORM_COGNITO_USER_POOL_ID: `ca-central-1_${rand(9)}`, PLATFORM_COGNITO_CLIENT_ID: rand(26),
  PLATFORM_STRIPE_SECRET_KEY: ["sk", "test", rand(32)].join("_"), PLATFORM_STRIPE_WEBHOOK_SECRET: ["whsec", rand(32)].join("_"),
  PLATFORM_SES_REGION: "ca-central-1", PLATFORM_BOLDSIGN_API_KEY: rand(40),
  PLATFORM_ZOOM_CLIENT_ID: rand(22), PLATFORM_ZOOM_CLIENT_SECRET: rand(32), PLATFORM_ZOOM_WEBHOOK_SECRET_TOKEN: rand(22),
  PLATFORM_SECRET_BOX_KEYS: `2:${key32()},1:${key32()}`, PLATFORM_SECRET_BOX_KEY_VERSION: "2",
  PLATFORM_LOCAL_SECRET: rand(40),
});
const secretValues = (env: Record<string, string>) => SECRET_SETTING_NAMES.flatMap((n) => (n === "PLATFORM_SECRET_BOX_KEYS" ? env[n].split(",").map((e) => e.slice(e.indexOf(":") + 1)) : [env[n]])).filter(Boolean);
const leaks = (text: string, values: string[]) => values.filter((v) => text.includes(v) || text.includes(encodeURIComponent(v)));
const portOpen = (port: number) => new Promise<boolean>((res) => { const s = createConnection({ host: "127.0.0.1", port }); s.once("connect", () => { s.destroy(); res(true); }); s.once("error", () => res(false)); });
const iso = (name: string, port: number, action: string, extra: string[] = []) => execFileSync("zsh", [join(STUDIO, "tools", "isolated.sh"), name, String(port), action, ...extra], { encoding: "utf8", cwd: STUDIO });
const get = (port: number, path: string) => fetch(`http://127.0.0.1:${port}${path}`, { headers: { connection: "close" }, signal: AbortSignal.timeout(15_000) });

console.log("== PF-24w DW1: PLATFORM_ENVIRONMENT is required, no default");
{
  const unset = refusal(() => loadPlatformConfig({})), blank = refusal(() => loadPlatformConfig({ PLATFORM_ENVIRONMENT: "  " }));
  const names = (e: ConfigRefused | null) => !!e && e.missing.join() === "PLATFORM_ENVIRONMENT" && e.environment === "unset" && /local, test or production/.test(e.message);
  const local = (() => { try { return loadPlatformConfig({ PLATFORM_ENVIRONMENT: "local" }); } catch (e) { return e as Error; } })();
  ok("PF-24w DW1 fail: loadPlatformConfig({}) throws ConfigRefused naming PLATFORM_ENVIRONMENT and the three values", names(unset), unset?.message ?? "loaded");
  ok("PF-24w DW1 fail: a blank PLATFORM_ENVIRONMENT (only spaces) throws the same", names(blank), blank?.message ?? "loaded");
  ok("PF-24w DW1 pass: { PLATFORM_ENVIRONMENT: \"local\" } loads, as local", !(local instanceof Error) && local.environment === "local", local instanceof Error ? local.message : undefined);
}

console.log("== PF-24w DW3: PF-4's rule, now in the loader: the local stand-in only where the environment is local");
{
  const env = generated();
  const local = (() => { try { return loadPlatformConfig({ PLATFORM_ENVIRONMENT: "local", PLATFORM_IDENTITY: "local" }); } catch (e) { return e as Error; } })();
  ok("PF-24w DW3 pass: local + PLATFORM_IDENTITY=local loads with the stand-in", !(local instanceof Error) && local.identity.via === "local", local instanceof Error ? local.message : undefined);
  for (const environment of ["production", "test"]) {
    const e = refusal(() => loadPlatformConfig({ ...env, PLATFORM_ENVIRONMENT: environment, PLATFORM_IDENTITY: "local" }));
    ok(`PF-24w DW3 fail: ${environment} + PLATFORM_IDENTITY=local is refused (every other setting complete: the stand-in alone is the reason)`,
      !!e && e.missing.length === 0 && e.invalid.length === 1 && e.invalid[0].name === "PLATFORM_IDENTITY" && /never runs in the test environment or production/.test(e.message), e?.message ?? "loaded");
  }
  const cognito = (() => { try { return loadPlatformConfig({ ...env, PLATFORM_ENVIRONMENT: "production", PLATFORM_IDENTITY: "cognito" }); } catch (e) { return e as Error; } })();
  ok("PF-24w DW3 pass: production + PLATFORM_IDENTITY=cognito loads (the rule refuses only the stand-in)", !(cognito instanceof Error) && cognito.identity.via === "cognito", cognito instanceof Error ? cognito.message : undefined);
}

console.log("== PF-24w DW4: identityConfig and sample-seed.ts read no variable themselves; read once, then kept");
{
  const files = ["api/src/platform/identity/port.ts", "api/src/platform/identity/sample-seed.ts"];
  const direct = (src: string) => [...src.matchAll(/(?:process\.)?env(?:\??\.)PLATFORM_[A-Z_]+|(?:process\.)?env\[\s*["'`]PLATFORM_/g)].map((m) => m[0]);
  const found = files.flatMap((f) => direct(readFileSync(join(STUDIO, f), "utf8")).map((m) => `${f}: ${m}`));
  ok("PF-24w DW4 fail: no env.PLATFORM_… or process.env.PLATFORM_… read in identity/port.ts or identity/sample-seed.ts (passing env on to the loader is allowed)", found.length === 0, found);
  ok("PF-24w DW4 fail: the scan is not blind (a direct read, dotted, optional or bracketed, is caught)", direct('const a = env.PLATFORM_IDENTITY; const b = process.env?.PLATFORM_X; const c = env["PLATFORM_Y"];').length === 3);
  // In this process: the first ask loads; a value set in process.env afterwards changes nothing.
  for (const k of SETTINGS.map((x) => x.name).concat("PLATFORM_ENVIRONMENT")) delete process.env[k];
  process.env.PLATFORM_ENVIRONMENT = "local";
  const { identityConfig } = await import("../api/src/platform/identity/port.ts");
  const { sampleSeedDecision } = await import("../api/src/platform/identity/sample-seed.ts");
  const before = identityConfig(), seedBefore = sampleSeedDecision();
  process.env.PLATFORM_IDENTITY = "local"; process.env.PLATFORM_SAMPLE_SEED = "on"; process.env.PLATFORM_ENVIRONMENT = "production"; process.env.PLATFORM_POOL_MFA_REQUIRED = "false";
  const after = identityConfig(), seedAfter = sampleSeedDecision();
  ok("PF-24w DW4 pass: identityConfig() and sampleSeedDecision() answer from the loaded configuration (local, no sign-in, no seed)", before.environment === "local" && before.identity === "none" && !seedBefore.run, { before, seedBefore });
  ok("PF-24w DW4 fail: values set only in process.env after the load change nothing (identity, environment, two-step rule, seed)", JSON.stringify(after) === JSON.stringify(before) && !seedAfter.run, { after, seedAfter });
  const forced = sampleSeedDecision(process.env, { forceOn: true });
  ok("PF-24w DW4 pass (break M1): forceOn answers from the loaded configuration (local: the demo reset seeds), with no re-load", forced.run && /local/.test(forced.why), forced);
  const demoSrc = readFileSync(join(STUDIO, "api", "src", "demo.ts"), "utf8");
  const copies = (src: string) => [...src.matchAll(/sampleSeedDecision\(\s*\{\s*\.\.\.process\.env/g)].length;
  ok("PF-24w DW4 fail (break M1): demo.ts never hands sampleSeedDecision a copy of process.env (a copy re-runs the loader on scrubbed settings)", copies(demoSrc) === 0 && copies('sampleSeedDecision({ ...process.env, X: "on" })') === 1);
  ok("PF-24w DW4 pass: given an env of its own, identityConfig reads it through the loader", identityConfig({ PLATFORM_ENVIRONMENT: "local", PLATFORM_IDENTITY: "local" }).identity === "local");
  for (const k of ["PLATFORM_IDENTITY", "PLATFORM_SAMPLE_SEED", "PLATFORM_ENVIRONMENT", "PLATFORM_POOL_MFA_REQUIRED"]) delete process.env[k];
}

console.log("== PF-24w DW5: the refusal never repeats a set value (PF-24's break m1)");
{
  const e = refusal(() => loadPlatformConfig({ PLATFORM_ENVIRONMENT: "sk_live_x" }));
  ok("PF-24w DW5 fail: PLATFORM_ENVIRONMENT=sk_live_x is refused with \"local, test or production\" and no sk_live (message and inspect)", !!e && /local, test or production/.test(e.message) && !inspect(e).includes("sk_live"), e ? inspect(e).slice(0, 300) : "loaded");
  const pasted = ["sk", "live", rand(24)].join("_");
  const e2 = refusal(() => loadPlatformConfig({ PLATFORM_ENVIRONMENT: "local", PLATFORM_IDENTITY: pasted, PLATFORM_SAMPLE_SEED: pasted }));
  ok("PF-24w DW5 fail: an unknown PLATFORM_IDENTITY or PLATFORM_SAMPLE_SEED is refused by name, never repeating the value (PF-4's own messages did)", !!e2 && e2.invalid.map((i) => i.name).sort().join() === "PLATFORM_IDENTITY,PLATFORM_SAMPLE_SEED" && !inspect(e2).includes(pasted), e2?.message ?? "loaded");
}

console.log("== PF-24w DW2 and J-15 W1: the real server");
const tsx = join(STUDIO, "node_modules", ".bin", "tsx");
/** main.ts started with only the given environment (no PLATFORM_ENVIRONMENT unless given), on its own port. */
const startBare = (env: Record<string, string>, port: number) => new Promise<{ code: number | null; out: string; listened: boolean }>((resolve) => {
  const varDir = mkdtempSync(join(tmpdir(), "pf24w-start-"));
  const p = spawn(tsx, ["--tsconfig", "api/tsconfig.json", "api/src/main.ts"], { cwd: STUDIO, env: { PATH: process.env.PATH ?? "", HOME: process.env.HOME ?? "", STUDIO_PORT: String(port), STUDIO_VAR: varDir, ...env }, stdio: ["ignore", "pipe", "pipe"] });
  let out = "", listened = false;
  const probe = setInterval(async () => { if (await portOpen(port)) listened = true; }, 200);
  p.stdout.on("data", (d) => (out += d)); p.stderr.on("data", (d) => (out += d));
  const timer = setTimeout(() => p.kill("SIGKILL"), 90_000);
  p.on("close", (code) => { clearInterval(probe); clearTimeout(timer); rmSync(varDir, { recursive: true, force: true }); resolve({ code, out, listened }); });
});
{
  const values = secretValues(generated());
  const bare = await startBare({ DATABASE_URL: "postgresql://xr_studio@127.0.0.1:54329/xr_studio_demo" }, PORT + 2);
  const closed = !(await portOpen(PORT + 2));
  ok("PF-24w DW2 fail: the API started with no PLATFORM_ENVIRONMENT exits non-zero before listening, its output naming the setting (port checked closed)",
    bare.code !== 0 && bare.code !== null && !bare.listened && closed && bare.out.includes("Missing required setting: PLATFORM_ENVIRONMENT.") && /local, test or production/.test(bare.out) && !bare.out.includes("Product Studio on http"), { code: bare.code, listened: bare.listened, out: bare.out.slice(-500) });
  ok("PF-24w J-15 W1 fail: start fails closed without the setting (the same spawn), and its output holds no secret value", bare.code !== 0 && !leaks(bare.out, values).length);
  // with local (and the stand-in, DW3's start): an isolated copy started with the setting given explicitly
  const L = `${NAME}_l`;
  try {
    const started = iso(L, PORT, "start", ["--ttl", "15", "PLATFORM_ENVIRONMENT=local", "PLATFORM_IDENTITY=local"]);
    const ready = await get(PORT, "/api/health/ready").then(async (r) => ({ status: r.status, body: await r.text() }), (e) => ({ status: 0, body: String(e) }));
    ok("PF-24w DW2 pass: with PLATFORM_ENVIRONMENT=local the API starts and answers /api/health/ready", /isolated .* on http/.test(started) && ready.status === 200, { started: started.slice(-200), ready });
    const local = await fetch(`http://127.0.0.1:${PORT}/api/platform/session/local`, { method: "POST", headers: { "content-type": "application/json", connection: "close" }, body: "{}", signal: AbortSignal.timeout(15_000) });
    ok("PF-24w DW3 pass: local + PLATFORM_IDENTITY=local starts with the stand-in's door open (it answers, not 403 LOCAL_SIGN_IN_OFF)", local.status !== 403 && local.status < 500, local.status);
  } finally { try { iso(L, PORT, "stop"); } catch { /* the copy stops itself by its ttl */ } }
}
{
  // J-15 W1: PLATFORM_ENVIRONMENT=test with every required setting; a preload wraps process.env in a Proxy that counts
  // each read of a setting's name in main.ts's process (Secret has no counter on main, so the count is at the env object).
  const env = generated(); delete env.DATABASE_URL;   // isolated.sh gives the copy its own database
  const values = secretValues(env);
  const dir = mkdtempSync(join(tmpdir(), "pf24w-count-")), counts = join(dir, "counts.json"), preload = join(dir, "count-env.mjs");
  // DATABASE_URL is left out: api/src/core.ts and Prisma read it themselves (outside api/src/platform/; settings.ts says so).
  const COUNTED = ["PLATFORM_ENVIRONMENT", ...SETTINGS.map((x) => x.name).filter((n) => n !== "DATABASE_URL")];
  writeFileSync(preload, `import { writeFileSync } from "node:fs";
const out = ${JSON.stringify(counts)}, names = ${JSON.stringify(COUNTED)};
if (/api[\\\\/]src[\\\\/]main\\.ts$/.test(process.argv[1] ?? "")) {
  const n = Object.fromEntries(names.map((k) => [k, 0])), stack = Object.fromEntries(names.map((k) => [k, []]));
  const target = process.env, seen = target.PLATFORM_ENVIRONMENT ?? null;   // the value main.ts starts with (the caller's, not isolated.sh's local)
  writeFileSync(out, JSON.stringify({ n, stack, seen }));
  // Node copying the whole environment for a child process (child_process normalizeSpawnArguments) is not a read of a
  // setting by the app: counted apart, as copies (reported, not asserted).
  let copies = 0; const copied = [];
  process.env = new Proxy(target, { get(o, k) { if (typeof k === "string" && k in n) { const at = new Error().stack ?? ""; if (at.includes("normalizeSpawnArguments")) { copies++; if (!copied.includes(k)) copied.push(k); writeFileSync(out, JSON.stringify({ n, stack, copies, copied, seen })); return Reflect.get(o, k); } n[k]++; if (stack[k].length < 3) stack[k].push(at.split("\\n").slice(2, 6).join(" | ")); writeFileSync(out, JSON.stringify({ n, stack, copies, copied, seen })); } return Reflect.get(o, k); } });
}
`);
  const T = `${NAME}_t`, TP = PORT + 1;
  const read = () => JSON.parse(readFileSync(counts, "utf8")) as { n: Record<string, number>; stack: Record<string, string[]>; copies?: number; copied?: string[]; seen?: string | null };
  try {
    const started = iso(T, TP, "start", ["--ttl", "15", "PLATFORM_ENVIRONMENT=test", `NODE_OPTIONS=--import=${preload}`, ...Object.entries(env).map(([k, v]) => `${k}=${v}`)]);
    const ready = await get(TP, "/api/health/ready").then((r) => r.status, () => 0);
    ok("PF-24w J-15 W1 pass: with PLATFORM_ENVIRONMENT=test and every required secret given, the API starts and answers /api/health/ready", /isolated .* on http/.test(started) && ready === 200 && existsSync(counts), { started: started.slice(-200), ready });
    const atStart = read();
    const notOnce = COUNTED.filter((k) => atStart.n[k] !== 1).map((k) => `${k}=${atStart.n[k]} ${atStart.stack[k]?.join(" || ").replaceAll(STUDIO + "/", "").slice(0, 900)}`);
    ok(`PF-24w J-15 W1 pass: at start each of the ${COUNTED.length} settings' names (every secret but DATABASE_URL, plus PLATFORM_ENVIRONMENT) is read exactly once: loadPlatformConfig ran once`, notOnce.length === 0, notOnce);
    ok("PF-24w J-15 W1 pass: the copy ran as PLATFORM_ENVIRONMENT=test (the caller's value won over isolated.sh's local)", atStart.seen === "test", atStart.seen);
    if (atStart.copies) console.log(`NOTE  J-15 W1: ${atStart.copies} setting names were copied into a child process's environment by Node (a spawn), not read by the app; the case below checks none was a secret`);
    const scrubbed = SECRET_SETTING_NAMES.filter((n) => n !== "DATABASE_URL"), toChild = (atStart.copied ?? []).filter((n) => scrubbed.includes(n));
    ok("PF-24w J-15 W1 fail: no secret setting (DATABASE_URL aside) reaches a child process's environment at start (the loader scrubs them first)", toChild.length === 0, toChild);
    const paths = ["/api/health/ready", "/api/health/live", "/api/session", "/api/platform/me", "/api/platform/staff", "/api/public/plans", "/api/no-such-route", "/", "/api/health", "/api/platform/session/local"];
    const answered = (await Promise.all(paths.map((p) => get(TP, p).then((r) => r.status, () => 0)))).filter((s) => s > 0).length;
    // Break M1 (#2635): the demo reset asks sampleSeedDecision after the loader has scrubbed process.env of its secrets;
    // a copy of process.env re-ran the loader there and the reset answered 500 in test. It must use the loaded one.
    const reset = await fetch(`http://127.0.0.1:${TP}/api/demo/reset`, { method: "POST", headers: { "x-actor": "user-A", "content-type": "application/json", connection: "close" }, body: JSON.stringify({ confirm: "RESET" }), signal: AbortSignal.timeout(180_000) }).then(async (r) => ({ status: r.status, body: (await r.text()).slice(0, 300) }), (e: Error) => ({ status: 0, body: e.message }));
    ok("PF-24w J-15 W1 pass (break M1): on the test copy, after the secrets are scrubbed, Demo › Reset answers (not 500, no ConfigRefused)", reset.status > 0 && reset.status < 500 && !/ConfigRefused|cannot start/.test(reset.body), reset);
    const later = read();
    const readAgain = COUNTED.filter((k) => later.n[k] !== atStart.n[k]).map((k) => `${k} +${later.n[k] - atStart.n[k]} ${later.stack[k]?.slice(-1)[0]?.slice(0, 300)}`);
    ok("PF-24w J-15 W1 fail: over ten later requests and a demo reset no setting is read again (zero reads: the configuration is kept, never re-read)", answered === 10 && readAgain.length === 0, { answered, readAgain });
  } finally { try { iso(T, TP, "stop"); } catch { /* the copy stops itself by its ttl */ } rmSync(dir, { recursive: true, force: true }); }
  const log = join(STUDIO, "var", "isolated-logs", `${T}-api.log`);
  const text = existsSync(log) ? readFileSync(log, "utf8") : "";
  ok("PF-24w J-15 W1 fail: the copy's captured log (PF-23's capture) holds no secret value", text.length > 0 && !leaks(text, values).length, { bytes: text.length, leaks: leaks(text, values).length });
  ok("PF-24w J-15 W1 fail: the leak finder is not blind (a line holding a seeded value is caught)", leaks(`x ${values[2]} y`, values).length === 1);
}

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
